use verus::prelude::*;

verus! {

    /// Given a vector `m` of 32-bit floating‐point numbers,
    /// returns a new vector containing the elements of `m` in reverse order.
    ///
    /// Specification:
    ///   - The result has the same length as `m`.
    ///   - For every index `i` in `0..m.len()`, `result[i] == m[m.len() - 1 - i]`.
    fn numpy_flip(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == m.len(),
        ensures
            forall |i: usize| i < m.len() ==> result[i] == m[m.len() - 1 - i]
    {
        let n = m.len();
        // We'll build the reversed vector by pushing one element at a time.
        let mut res: Vec<f32> = Vec::new();
        let mut i: usize = 0;

        // Loop invariant:
        //   1. 0 <= i <= n
        //   2. res.len() == i
        //   3. For all j < i, res[j] == m[n-1-j]
        while i < n
            invariant
                i <= n,
            invariant
                res.len() == i,
            invariant
                forall |j: usize| j < i ==> res[j] == m[n - 1 - j],
            decreases
                n - i
        {
            // Push the element at position (n-1-i) from m onto res
            res.push(m[n - 1 - i]);
            i += 1;
        }

        // At this point, i == n and res.len() == n, and by the invariant
        // res[j] == m[n-1-j] for all j < n.
        result = res;
    }

}